def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0))

    winners_est = int(supply // WATER_REQ)
    if winners_est < 1:
        winners_est = 1

    prev_bids = []
    threat_bid = 0.0
    eric_bid = None
    needy_count = 0
    rich_count = 0

    for oid, opp in alive:
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            needy_count += 1
        if opp.get('budget', 0) >= 200:
            rich_count += 1
        prev = opp.get('previous_trace') or {}
        b = prev.get('bid')
        if b is not None:
            prev_bids.append(float(b))
            if float(b) > threat_bid:
                threat_bid = float(b)
            if oid == 'Eric':
                eric_bid = float(b)

    if eric_bid is not None and eric_bid > threat_bid:
        threat_bid = eric_bid

    pressure = 0
    if winners_est <= 1:
        pressure += 2
    if len(alive) >= 3:
        pressure += 1
    if needy_count >= winners_est:
        pressure += 1
    if rich_count >= 2:
        pressure += 1
    if threat_bid >= 110:
        pressure += 2
    elif threat_bid >= 80:
        pressure += 1

    urgent = False
    if hp <= 3 or no_water_days >= 1:
        urgent = True

    if urgent:
        if threat_bid >= 120:
            bid = 121.5
        elif threat_bid >= 90:
            bid = threat_bid + 3.0
        else:
            bid = 78.0 if winners_est >= 2 else 96.0
    else:
        if winners_est >= 2:
            if pressure <= 1:
                bid = 24.0
            elif pressure == 2:
                bid = 34.0
            elif pressure == 3:
                bid = 46.0
            else:
                bid = 58.0
        else:
            if pressure <= 2:
                bid = 52.0
            elif pressure == 3:
                bid = 68.0
            else:
                bid = 84.0

        if eric_bid is not None:
            if eric_bid >= 120 and hp >= 5:
                bid = min(bid, 36.0)
            elif eric_bid <= 60 and winners_est >= 2:
                bid = max(bid, eric_bid + 2.0)

    if day >= 8 and hp >= 6 and budget < 160:
        bid *= 0.85
    if day >= 8 and urgent:
        bid = max(bid, 88.0)

    reserve_floor = 0.0
    days_left = 10 - day
    if days_left > 0 and hp >= 5:
        reserve_floor = min(budget * 0.35, days_left * 12.0)
    max_today = budget - reserve_floor
    if urgent:
        max_today = budget

    if max_today < 0:
        max_today = 0.0

    bid = min(bid, max_today, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 60

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], max(avg_prev * 1.1, 75))
    elif supply / (len(alive_opponents) + 1) < WATER_REQ:
        bid = min(my_status['budget'], max(avg_prev + 5, 80))
    else:
        bid = min(my_status['budget'], max(avg_prev * 0.9, 45))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Determine previous bids from opponents
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None and trace.get('status') != 'error':
            prev_bids.append(trace['bid'])

    # If first day or no previous data, use default
    if day == 1 or not prev_bids:
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.5)

    max_prev_bid = max(prev_bids)

    # Decide bid based on pressure from last round
    if max_prev_bid >= 100:
        # aggressive opponents; we need to compete
        target_bid = DAILY_SALARY * 0.7  # 98
        if hp <= 3:
            target_bid = max(target_bid, DAILY_SALARY * 0.9)
    else:
        # lower competition
        target_bid = DAILY_SALARY * 0.35  # 49
        if hp <= 3:
            target_bid = max(target_bid, DAILY_SALARY * 0.7)

    # Ensure we don't bid more than budget
    return min(budget, target_bid)
